  contract:{universal_subject_contract:'docs/SUBJECT_FILE_CONTRACT.md',architecture_contract:'docs/SUBJECT_FILE_CONTRACT.md#13-casekrav-profiler-og-evidensregistre',case_requirements_file:'data/fag/historie/case_requirements_historie_canonical_v1.json',claims_file:P.claims,sources_file:P.sources,place_evidence_file:P.evidence,data_production_contract:'docs/DATA_PRODUCTION_CONTRACT.md#historie-profil-og-evidenslag'},
  production_coverage:{total_subject_emner:230,emner_with_profile_case_candidates:0,emne_link_ratio_percent:0,cases_total:0,claims_total:0,sources_total:0,evidence_links_total:0,verified_cases_total:0,minimum_cases_total:4,minimum_verified_cases:4,minimum_evidence_links:8,minimum_mappings:7,status:'COMPLETE',completion_scope:'theory_specific_multi_case_evidence_foundation',interpretation:'Fire validerte Østfold-caser dokumenterer bronse- og jernalder, vikingtid, landskap, datering og bioarkeologiske kildegrenser. Profilen er en regional pilot og gjør ikke Østfold til universell modell for norsk forhistorie.'},
