upsert(manifest.profiles,'profile_id',{profile_id:PROFILE_OF,subject_id:'historie',geography_id:GEO_OF,profile_file:'historie/ostfold_forhistorie/profile.json',report_slug:'ostfold-forhistorie',status:'active_theory_evidence_profile',canonical_subject_version:'v5.8'});
contract.authoritative_files.ostfold_prehistory_profile = '../profiles/historie/ostfold_forhistorie/profile.json';

const claimMap = new Map([...A(claimsFile.claims)].map((c)=>[c.claim_id,c]));
