for (const e of A(evidenceFile.evidence_links)) { const xs=evidenceByClaim.get(e.claim_id)||[]; xs.push(e); evidenceByClaim.set(e.claim_id,xs); }
const deriveEntry = (theory_id, ids) => {
  const cs = ids.map((id)=>{ const c=claimMap.get(id); if(!c) throw new Error(`Missing claim ${id}`); return c; });
  const meta = theoryText[theory_id];
  return {theory_id,status:'evidence_ready',scope_status:'multi_case_geographic_pilot',universalization_status:'provisional_not_universal',claim_ids:ids,
    source_ids:sortNb(uniq(cs.flatMap((c)=>A(c.source_ids)))),case_ids:sortNb(uniq(cs.flatMap((c)=>A(c.scope?.case_ids)))),place_ids:sortNb(uniq(cs.flatMap((c)=>A(c.scope?.place_ids)))),emne_ids:sortNb(uniq(cs.flatMap((c)=>A(c.emne_ids)))),evidence_link_ids:sortNb(uniq(cs.flatMap((c)=>A(evidenceByClaim.get(c.claim_id)).map((e)=>e.evidence_id)))),
    evidence_dimensions:['documented_application','limitation_test','alternative_interpretation','multi_case_comparison','archaeological_dating_context_and_preservation'],rationale:meta.rationale,limitations:meta.limitations,alternative_interpretations:[meta.alt],disconfirmation_conditions:[meta.dis],scope_note:'Dette er et fler-case arkeologisk pilotgrunnlag med eksplisitte sted-, metode- og bevaringsgrenser og er ikke universelt bevis for teoriens gyldighet på tvers av alle perioder, geografier, befolkninger og materialtyper.'};
};
for (const [tid,ids] of Object.entries(theoryBundles)) upsert(theoryFile.entries,'theory_id',deriveEntry(tid,ids));
