claimsFile.claims.sort((a,b)=>a.claim_id.localeCompare(b.claim_id,'nb')); sourcesFile.sources.sort((a,b)=>a.source_id.localeCompare(b.source_id,'nb')); evidenceFile.evidence_links.sort((a,b)=>a.evidence_id.localeCompare(b.evidence_id,'nb')); oslo.cases.sort((a,b)=>a.case_id.localeCompare(b.case_id,'nb')); oslo.emne_case_mappings.sort((a,b)=>a.emne_id.localeCompare(b.emne_id,'nb')); ostfold.cases.sort((a,b)=>a.case_id.localeCompare(b.case_id,'nb')); ostfold.emne_case_mappings.sort((a,b)=>a.emne_id.localeCompare(b.emne_id,'nb')); manifest.profiles.sort((a,b)=>a.profile_id.localeCompare(b.profile_id,'nb'));

function refreshCoverage(profile) {
  const links=A(evidenceFile.evidence_links).filter((e)=>e.profile_id===profile.profile_id); const verified=A(profile.cases).filter((c)=>c.evidence_status==='claim_source_linked'); const claimIds=uniq(links.map((e)=>e.claim_id)); const sourceIds=uniq(links.flatMap((e)=>A(e.source_ids))); const mapped=uniq(A(profile.emne_case_mappings).map((m)=>m.emne_id)); const pc=profile.production_coverage||{};
  Object.assign(pc,{total_subject_emner:230,emners_with_profile_case_candidates:mapped.length,emne_link_ratio_percent:Math.round((mapped.length/230)*1000)/10,cases_total:A(profile.cases).length,verified_cases_total:verified.length,claims_total:claimIds.length,sources_total:sourceIds.length,evidence_links_total:links.length});
  const minV=Number(pc.minimum_verified_cases??10), minE=Number(pc.minimum_evidence_links??20); pc.status=(verified.length>=minV&&links.length>=minE)?'COMPLETE':'INCOMPLETE'; profile.production_coverage=pc;
  if (profile.migration_summary) { profile.migration_summary.validated_cases=verified.length; profile.migration_summary.unverified_case_candidates=A(profile.cases).length-verified.length; }
}
