doc=doc.replace(/Produksjonen står på 111 av 230[^\n]*Universell produksjonsstatus/, 'Produksjonen står på 120 av 230 etter at Forhistorie og arkeologi er fullført til 10/10 med Stunner, Nøstvet, Ekeberg, Solberg, Hunn, Tune og Gjellestad som eksisterende fysiske ankere, supplert av regional neolittisk syntese og eksplisitte bevaringsgrenser. Universell produksjonsstatus');
